"""Editable report/annotation documents from read-only observations, not Portal replicas."""
import json,pathlib,html,datetime,hashlib,zipfile
OUT=pathlib.Path.home()/'Downloads'/'MediQ_관제증적_20261020'
r=json.loads((OUT/'queries/runtime.json').read_text(encoding='utf8'))
def esc(v):return html.escape(str(v if v is not None else '기록 없음'))
def read(name):
 p=OUT/'queries'/f'{name}.json';return json.loads(p.read_text(encoding='utf8')) if p.exists() else {'status':'NOT VERIFIED','data':{}}
def table(headers,rows):return '<table><thead><tr>'+''.join('<th>'+esc(x)+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+esc(v)+'</td>' for v in row)+'</tr>' for row in rows)+'</tbody></table>'
def aggregate(pattern):
 import re
 return [x for x in r['auditAggregates'] if re.search(pattern,x['action'])]
def events_table(rows):return table(['이벤트','결과','사유','건수'],[(x['action'],x['result'],x['reason_code'] if x['reason_code'] and x['reason_code'].replace('_','').isalnum() else '상세 구조값 제외' if x['reason_code'] else '별도 코드 없음',x['events']) for x in rows])
def bars(rows):
 maxn=max([x['events'] for x in rows] or [1]);return ''.join('<div class="barrow"><b>'+esc(x['reason_code'] or x['action'])+'</b><span>'+str(x['events'])+'건</span><div class="track"><i style="width:'+str(100*x['events']/maxn)+'%"></i></div></div>' for x in rows)
groups={}
for e in r['helperEvents']:groups.setdefault(e['requestRef'],[]).append(e)
pairs=[]
for ref,es in groups.items():
 es.sort(key=lambda x:x['created_at']);start=next((x for x in es if x['reason_code'].endswith('_STARTED')),None);end=next((x for x in reversed(es) if not x['reason_code'].endswith('_STARTED')),None)
 duration=round((datetime.datetime.fromisoformat(end['created_at'])-datetime.datetime.fromisoformat(start['created_at'])).total_seconds()*1000) if start and end else None
 pairs.append((ref,start['created_at'] if start else '시작 기록 없음',end['created_at'] if end else '종료 기록 없음',str(duration)+' ms' if duration is not None else '산출 불가',end['reason_code'] if end else '종료 미확인'))
pages=[]
def add(slug,title,body,notes):pages.append(dict(slug=slug,title=title,body=body,notes=notes))
total=sum(x['events'] for x in r['auditAggregates']);deny=[x for x in r['auditAggregates'] if x['result'] in ['FAIL','DENIED','ERROR','FAILED']]
add('01-overview','관제 기록 · 전체 현황',f'<div class="stats"><div>보관 중 감사 이벤트<b>{total:,}건</b></div><div>이벤트·결과·사유 조합<b>{len(r["auditAggregates"])}개</b></div><div>현재 Control 상태<b>{esc(r["controlHealth"])}</b></div></div>'+bars(sorted(deny,key=lambda x:x['events'],reverse=True)[:6]),['집계는 DB에 현재 보관된 전체 기록입니다. 정상 시연·보안 시험 기록이 섞여 있어 거부 건수를 공격 건수로 해석하지 않습니다.','원본 질문·환자 식별정보·계정·토큰 값 없이 이벤트 종류와 결과만 조회했습니다.'])
add('02-qr-lifecycle','QR 티켓 · 생성에서 사용·철회까지',events_table(aggregate('^TICKET_')),['발급·상태 조회·접수 사용·철회·교체 및 재사용/만료 거부가 실제 감사기록에 존재합니다.','TICKET_REVOKED는 티켓 무효화입니다. 물리적 삭제를 뜻하지 않으며 삭제 이벤트는 이번 집계에서 확인되지 않았습니다.'])
add('03-consent','환자 동의 · 생성·조회·철회',events_table(aggregate('^CONSENT_')),['환자 동의가 생성되거나 철회된 사실을 별도 이벤트로 추적합니다.','QR 티켓 상태와 동의 상태는 서로 다른 정책 객체이며, 이 표는 각각의 처리 이력을 확인하는 자료입니다.'])
add('04-auth','로그인 · 인증 결과',events_table(aggregate('LOGIN|AUTHENTICAT')),['Entra 매핑 성공과 과거 합성 로그인 시험 기록을 사유 코드로 구분합니다.','서로 다른 시점의 시험 로그가 포함됩니다. 모든 로그인 기록을 현재 운영 인증 방식의 실적으로 합산하지 않습니다.'])
add('05-access','접근·단기 토큰 · 허용과 거부',events_table(aggregate('^TOKEN_|^ACCESS_|^POLICY_')[:20]),['역할·동의·병원·목적·영상 범위·DPoP 조건 등 거부 이유를 확인할 수 있습니다.','DPOP_PROOF_REQUIRED: 필요한 요청 서명 증명이 없습니다. DPOP_NONCE_REPLAYED: 이미 사용한 증명 식별자가 재사용됐습니다.'])
add('06-helper-results','건강도우미 · 처리 결과와 실패 코드',events_table(aggregate('^HEALTH_HELPER_')),['GENERATED 계열은 생성 완료 코드, EVIDENCE_DELIVERED는 근거 안내 코드입니다. 감사 사유 코드의 분류이며 별도 generationUsed 필드의 저장 증거는 아닙니다.','모델 연결 실패·입력 거부·임상 요청 안전 안내·근거 부족을 구분해 읽습니다. 질문 및 답변 원문은 수집하지 않았습니다.'])
add('07-helper-requests','건강도우미 · 요청별 시작·종료 연결',table(['요청 가명 ID','시작 UTC','종료 UTC','소요시간','최종 사유'],pairs[:10]),['동일 audit_session_id를 가명 ID로 변환해 시작·종료 이벤트를 연결했습니다. 최신 240개 로그에서 최대 10개 요청을 표시합니다.','소요시간은 감사 이벤트 시각의 차이입니다. 순수 모델 추론시간과 다르며, 짝이 없으면 임의로 계산하지 않습니다.'])
c=r['helperConnection']
add('08-helper-connection','건강도우미 · SSH·중계·모델 연결',table(['확인 항목','관측값'],[('SSH 전달 소켓',c.get('transport')),('중계 서비스',c.get('relay')),('모델 API',c.get('model')),('연결 확인 시각 UTC',c['observedAt']),('코드가 허용하는 모델 태그',r['helperLogCoverage']['modelTagInCode']),('실제 로드된 모델 버전/다이제스트','미확인')]),['현재 SSH 전달 경로는 UNAVAILABLE입니다. 중계와 모델 상태는 UNKNOWN으로, 모델 자체가 중지됐다고 단정할 수 없습니다.','qwen3.5:4b는 코드에서 확인한 허용 태그입니다. 요청 당시 실제 모델 버전·가중치 다이제스트를 입증하지 않습니다.'])
add('09-helper-coverage','건강도우미 · 요청한 관제 항목의 기록 범위',table(['필요 항목','현재 확인 결과'],[('요청 ID·처리 단계','audit_session_id 및 시작/종료 사유 코드'),('시작·종료·처리시간','동일 요청 로그를 연결해 계산 가능'),('모델 이름·버전','허용 태그만 확인 / 요청별 버전 기록 없음'),('지식베이스 버전','응답 계약에는 존재 / 감사 호출에는 미포함'),('근거 ID·개수','감사 호출에 미포함'),('실제 생성·대체 안내','사유 코드로 구분 / 별도 boolean 기록 없음'),('실패 코드','reason_code에 기록'),('연결 상태·확인 시각','상태 점검 응답에 존재')]),['현재 감사 호출은 요청 ID·행위·결과·사유를 기록하며 모델/근거/지식베이스 메타데이터를 전달하지 않습니다.','없는 값은 과거 로그에서 복원할 수 없습니다. 추가 수집 구현과 배포는 이번 증적 작성 범위에 포함하지 않았습니다.'])
add('10-image-key','영상·PACS·키 사용 승인 이력',events_table(aggregate('^PATIENT_KEY_|^KEY_RELEASE_|^PACS_')[:17]),['키 사용 준비·사전검증·사용 및 PACS 처리 이벤트를 관측했습니다. 암호키 원문은 조회하지 않았습니다.','이벤트 합계는 모든 영상 전송의 종단 성공이나 무결성 대조 완료를 뜻하지 않습니다. 요청별 원본 증적과 함께 확인해야 합니다.'])
add('11-db-storage','DB 저장 위치 · VM 컨테이너와 디스크',table(['항목','실제 관측값'],[('호스팅',r['storage']['kind']),('PostgreSQL 버전',r['storage']['version']),('데이터 경로',r['storage']['dataDirectory']),('볼륨 종류',r['storage']['volumeType']),('호스트 파일시스템',json.dumps(r['storage']['filesystem']['filesystems'],ensure_ascii=False)),('디스크',read('disk')['data'].get('name')),('디스크 암호화',read('disk')['data'].get('encryption',{}).get('type'))]),['현재 DB는 Azure 관리형 PostgreSQL이 아닌 Azure VM 내부 컨테이너입니다. DB 볼륨은 OS 디스크의 ext4 파일시스템에 있습니다.','EncryptionAtRestWithPlatformKey: Azure 플랫폼 관리 키로 디스크를 암호화합니다. 별도 Key Vault의 고객 관리 키 연결을 의미하지 않습니다.'])
add('12-db-fields','컬럼 보호 방식 · 해시와 암호문 구분',table(['테이블·컬럼','전체 행','값 존재','문자 길이'],[(x['table']+'.'+x['column'],x['rows'],x['present'],str(x['minLength'])+'–'+str(x['maxLength'])) for x in r['columnCounts']]),['토큰·재사용 방지·감사 무결성 해시를 확인했습니다. 실제 값은 조회하지 않고 존재 개수와 길이만 집계했습니다.','이번 컬럼명·코드 점검 범위에서 필드 암호문 및 비밀번호 해시 컬럼의 저장 증거는 확인하지 못했습니다. 감사로그 해시는 데이터 암호화가 아닙니다.'])
t=r['tls']
add('13-db-tls','DB TLS · 실제 연결과 평문 차단 설정',f'<div class="stats"><div>비TLS TCP 연결<b>{t["nonTlsTcp"]}개</b></div><div>HBA 구문 오류<b>{t["hbaErrors"]}개</b></div><div>서버 TLS 설정<b>{t["ssl"]}</b></div></div>'+table(['연결 역할','SSL','프로토콜','연결 수'],[(x['backend_type'],x['ssl'],x['version'],x['count']) for x in t['connections']])+table(['규칙','대상 DB','처리'],[(x['type'],','.join(x['database']),x['auth_method']) for x in r['hbaTlsDenyRules']]),['조회 시 앱 TCP와 DR 복제 연결 모두 TLS 1.3이며 비TLS TCP는 0개입니다. Unix 소켓은 네트워크 TLS 대상과 구분합니다.','hostnossl 거부 규칙을 재확인했습니다. 실제 평문 접속 거부 시험은 10월 19일 수행 증적이며 오늘 새로 수행한 시험으로 표시하지 않습니다.'])
v=read('vault');add('14-vault','Key Vault · 네트워크·삭제 보호',table(['항목','조회값'],[(k, json.dumps(val,ensure_ascii=False)) for k,val in v['data'].items()]),['Vault는 병원 저장 키 등 실제 용도별 보호와 연결해서 설명해야 합니다. DB 디스크는 플랫폼 관리 키를 사용합니다.','공개 네트워크 제한·RBAC·삭제 보호·사설 연결 상태는 각각의 통제입니다. 이 설정만으로 키 복구 시험 완료를 주장하지 않습니다.'])
roles=read('vaultRoles');add('15-vault-rights','Key Vault · 키 범위 접근 권한',table(['역할','주체 종류','권한 범위'],[(x['role'],x['principalType'],x['scope']) for x in roles['data']]) if isinstance(roles['data'],list) else '<pre>'+esc(roles)+'</pre>', ['병원 키 경로의 할당과 상속 권한을 조회했습니다. 계정명·주체 ID는 수집 결과에서 제외했습니다.','최소 권한 판단은 사용자·서비스의 용도와 역할의 실제 허용 연산을 함께 검토해야 합니다. 역할 이름만으로 안전성을 확정하지 않습니다.'])
d=read('vaultDiagnostics');add('16-sources','감사 수집 · Vault·WAF·Entra 확인 범위','<h2>Key Vault 진단 설정</h2><pre>'+esc(json.dumps(d,ensure_ascii=False,indent=2))+'</pre>'+table(['소스','현재 조회 결과'],[('WAF 컨테이너','실행 중 / 제한된 최근 24시간 Docker 로그에서 0바이트'),('Entra 작업 공간 조회','HTTP 200 / 해당 앱 최근 24시간 0건'),('Entra 진단 설정','권한 부족: AuthorizationFailed / Forbidden'),('라이선스에서 확인한 Entra 플랜','AAD_BASIC_EDU')]), ['Vault 로그 수집 대상과 활성 범주를 확인합니다. WAF는 기존 Coraza 컨테이너이며 Azure 관리형 WAF와 구분합니다.','0건은 수집 정상의 증거가 아닙니다. Entra 진단 설정을 읽지 못했으며, WAF의 다른 저장 경로는 이번 제한 조회에 포함되지 않았습니다.'])
style='''*{box-sizing:border-box}body{margin:0;background:#f0f4f9;color:#172d47;font-family:Pretendard,'Malgun Gothic',sans-serif}header{padding:28px 36px;background:#e3e9f1;border-bottom:4px solid #275cc2}h1{font-size:30px;margin:12px 0}h2{font-size:21px}p{line-height:1.6}small{font-size:14px;color:#52657b}.layout{display:grid;grid-template-columns:minmax(0,1fr) 360px;gap:24px;padding:28px}.original .layout{grid-template-columns:1fr}.content{background:white;padding:20px;border:1px solid #d4deeb;border-radius:8px}.annotated .content{outline:4px solid #df3034;outline-offset:-4px}.notes{display:grid;align-content:start;gap:30px}.note{background:white;border:4px solid #eac600;color:#111;padding:20px;font-size:19px;line-height:1.65}.arrow{color:#dc3034;font-size:30px;font-weight:700}table{width:100%;border-collapse:collapse;table-layout:fixed;font-size:15px}td,th{text-align:left;border-bottom:1px solid #dae1eb;padding:11px 9px;overflow-wrap:anywhere}th{background:#eef3fa;font-weight:700}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:16px;line-height:1.55}.stats{display:flex;gap:15px;margin:6px 0 25px}.stats>div{flex:1;background:#eef3fc;padding:16px}.stats b{display:block;font-size:29px;margin-top:10px}.barrow{position:relative;margin:20px 0;font-size:15px}.barrow span{float:right}.track{height:12px;background:#e8edf5;margin-top:9px}.track i{display:block;height:100%;background:#c85959}footer{padding:20px 36px;font-size:14px;color:#52657b}'''
for p in pages:
 for mode in ['original','annotated']:
  notes=''.join('<div class="note"><span class="arrow">←</span> '+esc(n)+'</div>' for n in p['notes']) if mode=='annotated' else ''
  doc=f'<!doctype html><html lang="ko"><meta charset="utf-8"><title>{esc(p["title"])}</title><style>{style}</style><body class="{mode}"><header><small>MEDI Q · LIVE READ-ONLY OBSERVATIONS · 증적 {p["slug"]}</small><h1>{esc(p["title"])}</h1><small>실제 조회 결과 정리 화면 · Azure Portal / 서비스 관제 화면 캡처 아님<br>서버 관측 UTC {esc(r["observedAt"])} · Azure 설정의 관측 시각은 queries/*.json 참조</small></header><div class="layout"><main class="content">{p["body"]}</main><aside class="notes">{notes}</aside></div><footer>계정·IP·환자 식별정보·키·토큰·질문 원문 제외 | 표시는 보관 중 기록의 조회 시점 결과 | 원본 및 설명본 분리 보관</footer></body></html>'
  (OUT/mode/(p['slug']+'.html')).write_text(doc,encoding='utf8')
  if mode=='annotated':(OUT/'editable'/(p['slug']+'.html')).write_text(doc,encoding='utf8')
index='<h1>Medi Q 관제 증적 · 2026-10-20</h1><p>실시간 조회 결과를 정리한 화면입니다. 실제 관제·Portal 새 촬영은 브라우저 연결 실패로 미확보입니다. 원본은 값 조회를 제한한 보고 화면이며 주석본에는 설명 레이어를 추가했습니다.</p>'+''.join(f'<article><h2>{esc(p["title"])}</h2><a href="original/{p["slug"]}.png">원본 화면</a> · <a href="annotated/{p["slug"]}.png">주석 PNG</a> · <a href="editable/{p["slug"]}.html">편집용 HTML</a><br><img style="max-width:100%" loading="lazy" src="annotated/{p["slug"]}.png"></article>' for p in pages)
(OUT/'index.html').write_text('<!doctype html><html lang="ko"><meta charset="utf-8"><style>body{font-family:Malgun Gothic;max-width:1600px;margin:30px auto;background:#eef2f8}article{padding:20px;background:white;margin:20px 0}a{color:#245cc2}</style>'+index,encoding='utf8')
(OUT/'capture-plan.json').write_text(json.dumps([{k:p[k] for k in ['slug','title','notes']} for p in pages],ensure_ascii=False,indent=2),encoding='utf8')
print(json.dumps({'pages':len(pages),'folder':str(OUT)},ensure_ascii=False))
